function escapeXml(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}

function replaceEmoji(str) {
    if (!str) return "";
    const EMOJI_MAP = {
        31: "😳", 21: "😍", 11: "🙄", 32: "😎", 12: "😭", 43: "☺️", 50: "🤐", 45: "😴", 19: "😂", 37: "😡",
        47: "😱", 26: "🤪", 4: "😁", 40: "😞", 36: "🤓", 17: "😓", 24: "😫", 51: "🥴", 33: "🤭", 7: "🙂",
        49: "😪", 16: "🥵", 14: "😥", 5: "😄", 46: "🤠🚬", 29: "💪", 44: "🤬", 39: "😄❓", 18: "🤫", 13: "😵",
        28: "😣", 20: "😢", 30: "💀", 22: "🤕🔨", 34: "😄👏", 10: "👆🏻🐽", 1: "👏", 23: "😑", 8: "😏",
        41: "😧", 15: "🖕🏻", 38: "🙁", 58: "😒", 9: "😙", 60: "😮", 6: "🥺", 54: "🔪", 48: "🐷", 2: "🌹",
        42: "💋", 53: "❤️", 56: "💔", 52: "🌙", 55: "🎁", 25: "🤗", 35: "👍🏻", 3: "🤝", 59: "✌🏻️",
        27: "🙏", 57: "👊🏻", 61: "🤨", 62: "😴", 63: "👏🏻", 64: "🐲"
    };
    return str.replace(/\[fn=(\d+)\]/g, (m, id) => EMOJI_MAP[id] || m);
}

function splitContentIOS(c) {
    return c.replace(/<p>/g, "").replace(/<\/p>/g, "\n").split("\n").map(x => x.trim()).filter(Boolean);
}

function splitContentAndroid(c) {
    return c.replace(/(<img[^>]*?>)<\/p>/g, "$1</p>").split("</p>");
}

function splitParagraphs(content) {
    let cleanedContent = (content || '').replace(/\r/g, '').trim();
    let rawParagraphs = cleanedContent.split('\n');
    for (let i = 0; i < rawParagraphs.length; i++) {
        rawParagraphs[i] = rawParagraphs[i].trim();
    }
    let paragraphs = [null];
    for (let i = 0; i < rawParagraphs.length; i++) {
        paragraphs[i + 1] = rawParagraphs[i];
    }
    return paragraphs;
}

