function createGodCommentSvg(godItem) {
    const w = 1000, h = 140, pad = 32, tw = 140, th = 56;
    let contentText = godItem.text || godItem.Content || "";
    let txt = escapeXml.call(this, replaceEmoji(contentText));
    let dtxt = txt.length > 18 ? txt.slice(0, 18) + "..." : txt;
    let cy = h / 2 + 14;
    return `<svg width="${w}" height="${h}" xmlns="http://www.w3.org/2000/svg">
<rect width="100%" height="100%" fill="rgba(255,255,255,0.5)" rx="70"/>
<rect x="${pad}" y="${(h - th) / 2}" width="${tw}" height="${th}" rx="30" fill="#FF4444"/>
<text x="${pad + tw / 2}" y="${cy}" font-size="32" fill="#FFF" text-anchor="middle" font-weight="bold">热评</text>
<text x="${pad + tw + 24}" y="${cy}" font-size="40" fill="#000" font-weight="bold">${dtxt}</text>
</svg>`;
}

function getQdCommentsData(bid, cid) {
    const { java } = this;
    let result = {
        idea: [],
        god: [],
        chapter: { totalCount: 0, dataList: [] }
    };
    try {
        let ideaRes = java.ajax(`https://qidian.${hq}/dpsj.php?bookId=${bid}&chapterId=${cid}`);
        if (ideaRes) {
            try {
                let ideaData = JSON.parse(ideaRes);
                result.idea = ideaData?.Data?.Getparagraphscommentcounts?.DataList || [];
            } catch (e) {}
        }
        try {
            let godRes = java.ajax(`https://qidian.${hq}/qdsp.php?bookId=${bid}&chapterId=${cid}`);
            if (godRes) {
                let godData = JSON.parse(godRes);
                result.god = godData?.Data?.Reviews || [];
            }
        } catch (e) {}
        try {
            let chapterRes = java.ajax(`https://qidian.${hq}/bzsj.php?bookId=${bid}&chapterId=${cid}`);
            if (chapterRes) {
                let chapterData = JSON.parse(chapterRes);
                result.chapter = {
                    totalCount: chapterData?.Data?.Getchapterendcomments?.TotalCount || 0,
                    dataList: chapterData?.Data?.Getchapterendcomments?.DataList || []
                };
            }
        } catch (e) {}
    } catch (e) {}
    return result;
}

