function createQdChapterSvg(totalCount, dataList) {
    const width = 1000;
    const padding = 32;
    const headerH = 56;
    const gap = 24;
    let y = padding;
    let chapterSvg = `<svg width="${width}" height="1" xmlns="http://www.w3.org/2000/svg">
<rect width="100%" height="100%" fill="rgba(255,255,255,0.5)" rx="60"/>
<text x="40" y="${y+42}" font-size="42" fill="#000000" font-weight="bold">本章说</text>
<text x="${width-40}" y="${y+42}" font-size="40" fill="#000000" text-anchor="end" font-weight="bold">${totalCount} 条评论 〉</text>
`;
    y += headerH + 20;
    dataList.forEach(item => {
        let uname = escapeXml(item.UserName || "匿名");
        let like = item.AgreeAmount || 0;
        let likeStr = like.toString();
        let contentTxt = escapeXml(replaceEmoji(item.Content || ""));
        let likeW = 100 + likeStr.length * 22;
        let likeX = width - padding - likeW;
        let lines = [];
        let line = "";
        let maxLineLength = 18;
        for (let i=0; i<contentTxt.length; i++) {
            line += contentTxt[i];
            if (line.length >= maxLineLength) {
                lines.push(line);
                line = "";
            }
        }
        if (line) lines.push(line);
        let showLines = lines.slice(0, 4);
        if (lines.length > 4) {
            let lastLine = showLines[3];
            if (lastLine.length >= maxLineLength - 1) {
                showLines[3] = lastLine.substring(0, maxLineLength - 1) + "…";
            } else {
                showLines[3] = lastLine + "…";
            }
        }
        chapterSvg += `<text x="40" y="${y+40}" font-size="40" fill="#000000" font-weight="bold">${uname}</text>`;
        chapterSvg += `<rect x="${likeX}" y="${y+10}" width="${likeW}" height="56" rx="28" fill="rgba(0,0,0,0.1)"/>`;
        chapterSvg += `<g transform="translate(${likeX+24},${y+18}) scale(0.04)">`;
        chapterSvg += `<path d="M560.6 410.36l243.84-14.20000031a133.75999969 133.75999969 0 0 1 128.71999969 170.16l-36.72 129.80000062-2.55999938 9.07999969c-47.32000031 168.84-125.59999969 258.31999969-236.4 258.31999969H221.04000031A141.07999969 141.07999969 0 0 1 80 822.39999969v-290.91999938C80 459.2 127.68000031 416.12 211.11999969 392a197.28 197.28 0 0 0 123.56000062-119.20000031l55.63999969-150.96a101.04 101.04 0 0 1 192.64000031 9.72c19.84000031 76.92 9.36 166.32-30.28000031 267.92000062a7.99999969 7.99999969 0 0 0 7.92 10.87999969z m3.72 63.88000031a72 72 0 0 1-71.28-98.04c35.11999969-90 44.08000031-166.15999969 27.96-228.64000031a37.03999969 37.03999969 0 0 0-70.60000031-3.6L394.71999969 294.99999969A261.76000031 261.76000031 0 0 1 230 453.2c-60.24 17.44000031-85.96000031 40.68-85.96000031 78.36v290.92000031c0 42.55999969 34.51999969 77.08000031 77.08000031 77.07999938h436.39999969c75.52000031 0 134.32000031-67.2 174.80000062-211.59999938l2.59999969-9.20000062 36.72-129.79999969c1.72000031-6.19999969 2.59999969-12.55999969 2.59999969-19.00000031 0-38.52-31.2-69.76000031-67.87999969-69.84l-241.99999969 14.16z" fill="#000000"/>`;
        chapterSvg += `</g>`;
        chapterSvg += `<text x="${likeX+75}" y="${y+50}" font-size="32" fill="#000000" font-weight="bold">${likeStr}</text>`;
        for (let i=0; i<showLines.length; i++) {
            chapterSvg += `<text x="40" y="${y+100 + i*50}" font-size="40" fill="#000000" font-weight="bold">${showLines[i]}</text>`;
        }
        let realItemHeight = 100 + showLines.length * 50 + 40;
        y += realItemHeight + gap;
    });
    chapterSvg += `</svg>`;
    chapterSvg = chapterSvg.replace(/height="1"/, `height="${y}"`);
    return chapterSvg;
}

function qidianggetComments(content, bid, cid) {

const { java, cache } = this;
    try {
        let { idea, god, chapter } = getQdCommentsData.call(this, bid, cid);
        let paragraphs = splitParagraphs(content);
        let date = Date.now() + "";
        idea.forEach(item => {
            let paragraphId = Number(item.ParagraphId);
            if (paragraphId > 0 && paragraphId < paragraphs.length && paragraphs[paragraphId]) {
                let count = Math.min(item.TextCount || 0, 99);
                if (count > 0) {
                    cache.putMemory(`qd-${bid}-${cid}-${paragraphId}-text`, paragraphs[paragraphId]);
                    let svgUrl = createCommentSvg.call(this, count, bid, cid, paragraphId, null, 'qd');
                    paragraphs[paragraphId] += `<img src="${svgUrl}">`;
                }
            }
        });
        let godByPara = {};
        god.forEach(item => {
            let pid = item.ParagraphId;
            if (!godByPara[pid]) godByPara[pid] = item;
        });
        Object.keys(godByPara).forEach(k => {
            let paragraphId = parseInt(k);
            if (paragraphId <= 0 || paragraphId >= paragraphs.length || !paragraphs[paragraphId]) return;
            let item = godByPara[k];
            let svg = createGodCommentSvg.call(this, item);
            let b64 = java.base64Encode(svg);
            let click = `showQdCmt('${bid}','${cid}','${paragraphId}','${date}')`;
            paragraphs[paragraphId] += `\n<img src="data:image/svg+xml;base64,${b64},{"style":"FULL","type":"god","click":"${click}"}">`;
        });
        let result = paragraphs.slice(1).join("\n");
        if (chapter.totalCount > 0) {
            let svg = createQdChapterSvg.call(this, chapter.totalCount, chapter.dataList);
            let b64 = java.base64Encode(svg);
            let click = `showQdChapter('${bid}','${cid}','${date}')`;
            result += `<img src="data:image/svg+xml;base64,${b64},{"style":"FULL","type":"chapter","click":"${click}"}">`;
        }
        return result;
    } catch (e) { 
        return content; 
    }
}

