function loginQidian() {
    try {
        // 使用 startBrowserAwait 打开起点登录页面
        const url = "https://www.qidian.com/";
        const title = "起点登录";

        // 等待用户登录完成
        try {
            java.startBrowserAwait(url, title);
        } catch (e) {
            java.toast("登录过程中发生错误: " + e.message);
            java.log("登录过程中发生错误: " + e.message);
            return false;
        }
        // 获取登录结果
        try {
            const qdCookie = cookie.getCookie("qidian.com");
            if (!qdCookie || qdCookie === "" || !qdCookie.includes("ywkey") || !qdCookie.includes("ywguid")) {
                java.toast("获取登录信息失败");
                java.log("获取登录信息失败: " + qdCookie);
                return false;
            }
            const ywkeyMatch = qdCookie.match(/ywkey=([^;]+)/);
            const ywguidMatch = qdCookie.match(/ywguid=([^;]+)/);
            if (ywkeyMatch && ywguidMatch) {
                const ywkey = ywkeyMatch[1];
                const ywguid = ywguidMatch[1];
                java.toast("登录成功: " + ywkey + ", " + ywguid);
                java.log("登录成功: " + ywkey + ", " + ywguid);
                onLoginSuccess(ywkey, ywguid);
            } else {
                java.toast("解析登录信息失败");
                java.log("解析登录信息失败: " + qdCookie);
                return false;
            }
        } catch (e) {
            java.toast("获取登录信息过程中发生错误: " + e.message);
            java.log("获取登录信息过程中发生错误: " + e.message);
            return false;
        }
    } catch (e) {
        java.toast("登录失败: " + e.message);
        java.log("登录失败: " + e.message);
        return false;
    }
}

function onLoginSuccess(ywkey, ywguid) {
    try {
        const url = `${source.bookSourceUrl}/api/uploadTempUser?ywkey=${encodeURIComponent(ywkey)}&ywguid=${encodeURIComponent(ywguid)}`;
        const options = {
            headers: {
                "Content-Type": "application/json"
            }
        };
        try {
            const response = java.ajax(`${url},${JSON.stringify(options)}`);
            const responseData = JSON.parse(response);
            if (responseData.error) {
                java.toast("上传用户信息失败: " + responseData.error);
                java.log("上传用户信息失败: " + responseData.error);
                return false;
            }
            const tag = responseData.tag;
            if (tag) {
                java.toast("用户信息上传成功, tag: " + tag );
                java.log("用户信息上传成功, tag: " + tag);
                cache.put("userTag", tag);
            } else {
                java.toast("用户信息上传成功, 但未获取到tag");
                java.log("用户信息上传成功, 但未获取到tag: " + response);
            }
        } catch (e) {
            java.toast("上传用户信息过程中发生错误，使用「重新上传」");
            java.log("上传用户信息过程中发生错误: " + e.message);
            return false;
        }
    } catch (e) {
        java.toast("上传用户信息失败: " + e.message);
        return false;
    }
    return true;
}

function reUploadUserInfo() {
    const qdCookie = cookie.getCookie("qidian.com");
    if (!qdCookie || qdCookie === "" || !qdCookie.includes("ywkey") || !qdCookie.includes("ywguid")) {
        java.toast("未登录，请先「登录起点」");
        return false;
    }
    const ywkeyMatch = qdCookie.match(/ywkey=([^;]+)/);
    const ywguidMatch = qdCookie.match(/ywguid=([^;]+)/);
    if (ywkeyMatch && ywguidMatch) {
        const ywkey = ywkeyMatch[1];
        const ywguid = ywguidMatch[1];
        return onLoginSuccess(ywkey, ywguid);
    } else {
        java.toast("解析登录信息失败");
        java.log("解析登录信息失败: " + qdCookie);
        return false;
    }
}

