}

function copyUserTag() {
    const userTag = cache.get("userTag");
    if (userTag) {
        let htmlContext = `<doctype html>
<html>
    <body>
        <p>用户标签: <code>${userTag}</code></p>
        <button onclick="copyToClipboard()">复制标签</button>
        <script>
            function copyToClipboard() {
                navigator.clipboard.writeText('${userTag}').then(() => {
                    alert('标签已复制到剪贴板');
                }, (err) => {
                    alert('复制失败: ' + err);
                });
            }
        </script>
    </body>
</html>`;
        java.startBrowser(`data:text/html;charset=utf-8;base64, ${java.base64Encode(htmlContext)}`, '复制最新 Tag')
    } else {
        java.toast("未找到用户标签，请先登录并上传用户信息");
    }
}

function logout(){
